[ExtensionOf(classStr(PriceDisc))]
public final class GUPPriceDisc_Extension
{
    private SalesPurchLineInterface salesPurchLineInterface;
    private boolean useMarginAdjustment = true;

}

Method.Source:
    protected boolean findPriceAgreements(boolean _findAll, boolean _findProductDim, boolean _useItemPrice, PriceGroupId _priceGroupId, InventDim _inventDimAllActivated, InventDim _inventDimProductDimActivated, boolean _findBlank)
    {
        GUPPriceEnginePriceDiscoveryEngine priceDiscoveryEngine;
        boolean ret;

        if (this.parmPriceDiscParameters().parmModuleType() == ModuleInventPurchSales::Sales && FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
        {
            SalesLine salesLine = salesPurchLineInterface.parmSalesPurchLine();
            SalesTable salesTable = SalesTable::find(salesLine.SalesId);

            priceDiscoveryEngine = new GUPPriceEnginePriceDiscoveryEngine(GUPPriceEngineJournalSearchEngine::getInstance().doSearch(salesTable, salesLine));

            ret = this.findGUPPriceAgreement(priceDiscoveryEngine);

            if (ret)
            {
                _findAll = false;
                _findProductDim = false;
                _useItemPrice = false;
                _findBlank = false;
            }
        }

        ret = next findPriceAgreements(_findAll, _findProductDim, _useItemPrice, _priceGroupId, _inventDimAllActivated, _inventDimProductDimActivated, _findBlank) || ret;

        if (this.parmPriceDiscParameters().parmModuleType() == ModuleInventPurchSales::Sales && FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) && useMarginAdjustment)
        {
            this.applyMarginAdjustment(priceDiscoveryEngine, this.parmPrice());
        }

        return ret;
    }

    public boolean findItemPrice()
    {
        boolean ret = next findItemPrice();

        if (this.parmPriceDiscParameters().parmModuleType() == ModuleInventPurchSales::Sales && FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
        {
            GUPItemBasePriceParameter parameter = GUPItemBasePriceParameter::construct();
            parameter.initFromSalesPurchLineInterface(this.salesPurchLineInterface);
            ret = this.findGUPBasePrice(parameter) || ret;
        }

        return ret;
    }

    public SalesPurchLineInterface parmSalesPurchLineInterface(SalesPurchLineInterface _salesPurchLineInterface = null)
    {
        if (_salesPurchLineInterface)
        {
            this.salesPurchLineInterface = _salesPurchLineInterface;
        }

        return this.salesPurchLineInterface;
    }

    private boolean findGUPPriceAgreement(GUPPriceEnginePriceDiscoveryEngine _priceDiscoveryEngine)
    {
        boolean ret;
        
        GUPPriceEngineDecoratedPriceLine matchedJournalLine = _priceDiscoveryEngine.findTradeAgreementBasePrice();

        if (matchedJournalLine)
        {
            this.parmPrice(matchedJournalLine.parmPrice());
            GUPPriceEngineTradeAgreementLine tradeAgreementLine = matchedJournalLine.parmJournalLine();
            this.mcrPriceDiscTableFound(tradeAgreementLine.parmPriceDiscTable());
            this.useMarginAdjustment = tradeAgreementLine.parmPriceDiscTable().PriceApplyAdjustment;
            ret = true;
        }

        return ret;
    }

    private boolean findGUPBasePrice(GUPItemBasePriceParameter _parameter)
    {
        boolean ret;
        real priceFound = GUPItemBasePrice::getItemBasePrice(_parameter);

        if (priceFound)
        {
            this.parmPrice(priceFound);
            ret = true;
        }

        return ret;
    }

    private void updateMarginComponentAdjustmentHistory(List _decoratedAdjustmentValueLineList)
    {
        Price                                       amount;
        Name                                        marginComponentCode;
        Name                                        marginComponentAdjustment;
        GUPCalculationSequenceNum                   calculationSequence;
        GUPPriceEngineMarginCodeLine                marginCodeLine;
        SalesLineRefRecId                           salesLineRefRecid = salesPurchLineInterface.parmSalesPurchLine().RecId;
        GUPMarginComponentAdjustmentHistory         marginComponentAdjustmentHistory;
        ListEnumerator                              enum = _decoratedAdjustmentValueLineList.getEnumerator();
        GUPPriceEngineDecoratedAdjustmentValueLine  adjustmentValueLine;

        if (!salesLineRefRecid)
        {
            return;
        }

        GUPMarginComponentAdjustmentHistory::deleteHistory(salesLineRefRecid);

        while (enum.moveNext())
        {
            adjustmentValueLine = enum.current();
            amount = adjustmentValueLine.parmComputedPrice();
            marginCodeLine = adjustmentValueLine.parmJournalLine();
            calculationSequence = marginCodeLine.parmComponentSetup().CalculationSequence;
            marginComponentAdjustment = marginCodeLine.parmComponentHeader().OfferId;
            marginComponentCode = GUPPriceComponentCode::find(marginCodeLine.parmComponentHeader().MarginComponentCode).Name;

            ttsbegin;
            marginComponentAdjustmentHistory.clear();
            marginComponentAdjustmentHistory.SalesLine = salesLineRefRecid;
            marginComponentAdjustmentHistory.MarginComponentCode = marginComponentCode;
            marginComponentAdjustmentHistory.marginComponentAdjustment = marginComponentAdjustment;
            marginComponentAdjustmentHistory.CalculationSequence = calculationSequence;
            marginComponentAdjustmentHistory.Amount = amount;
            marginComponentAdjustmentHistory.insert();
            ttscommit;
        }
    }
